// artifacts/yard/parts/drive_fusion_main.ts
function build2() {
  const root = new Group;
  root.name = "drive_fusion_main";
  const effects = [];
  flange(root, metal, [0, 0, 0], [0, -1, 0]);
  const TF = 1.1;
  for (const [x, z] of [[-TF, -TF], [TF, -TF], [TF, TF], [-TF, TF]]) {
    strut(root, metal, [x, 0.1, z], [x, 1.2, z], 0.1, 4);
  }
  for (const y of [0.3, 1]) {
    for (let c = 0;c < 4; ++c) {
      const corners = [[-TF, -TF], [TF, -TF], [TF, TF], [-TF, TF]];
      const p0 = corners[c], p1 = corners[(c + 1) % 4];
      strut(root, metal, [p0[0], y, p0[1]], [p1[0], y, p1[1]], 0.07, 4);
    }
  }
  tube(root, dark, 0.55, 0.55, 0.3, [0, 1.2, 0], 6);
  tube(root, lightArmor, 0.6, 1.4, 2.5, [0, 1.3, 0], 6);
  tube(root, black, 0.5, 1.3, 2.4, [0, 1.35, 0], 6);
  tube(root, glow, 0.48, 0.48, 0.08, [0, 1.25, 0], 6);
  tube(root, metal, 1.42, 1.42, 0.12, [0, 3.8, 0], 6);
  for (const sx of [-1, 1]) {
    strut(root, metal, [sx * 1.1, 1.8, 0], [sx * 2.8, 2.5, 0], 0.06, 4);
    box(root, dark, [0.06, 2, 0.8], [sx * 2.8, 2.5, 0]);
    strut(root, metal, [0, 1.8, sx * 1], [0, 2.5, sx * 2.2], 0.06, 4);
    box(root, dark, [0.6, 1.6, 0.06], [0, 2.5, sx * 2.2]);
  }
  for (const sx of [-1, 1]) {
    for (const sz of [-1, 1]) {
      box(root, metal, [0.15, 0.15, 0.15], [sx * 2.85, 3.2, sz * 0.5]);
      box(root, dark, [0.1, 0.2, 0.1], [sx * 2.85, 3.2, sz * 0.5]);
    }
  }
  for (const angle of [0, Math.PI / 2, Math.PI, 3 * Math.PI / 2]) {
    const r = 0.7;
    strut(root, copper, [Math.cos(angle) * r, 0.3, Math.sin(angle) * r], [Math.cos(angle) * 0.55, 1.2, Math.sin(angle) * 0.55], 0.04, 3);
  }
  effect_cone(root, effects, {
    name: "flame",
    radius: 1.15,
    length: 7,
    pos: [0, 3.85, 0],
    material: exhaust
  });
  return root;
}
