// artifacts/yard/designs/truss_proof.ts
function place(root, obj, pos, rot = [0, 0, 0]) {
  obj.position.set(...pos);
  obj.rotation.set(...rot);
  root.add(obj);
}
function build5() {
  const root = new Group;
  root.name = "design_truss_proof";
  root.add(build());
  place(root, build2(), [0, -10, 0], [0, 0, Math.PI]);
  place(root, build3(), [0, 10, 0]);
  place(root, build4(), [0, 14, 0]);
  return root;
}

